INSERT INTO t_account_no_sequence (id, ledger_book_id, chart_account_id, `last_value`, create_time, update_time)
VALUES (#{id}, #{ledgerBookId}, #{chartAccountId}, LAST_INSERT_ID(1), #{now}, #{now})
ON DUPLICATE KEY UPDATE `last_value` = LAST_INSERT_ID(`last_value` + 1), update_time = #{now}
